using System.Net;
using SysAdminAssistant.Core;
public static class AgentGaugeSpecs
{
 public static void Run(Action<string,bool> check){
 var now=DateTime.UtcNow;var p=new AgentPolicy{StandardServices=false};var r=new AgentReport{MachineName="fixture",Os="Windows",CpuPercent=25,CpuCount=4,MemoryTotalBytes=1000,MemoryAvailableBytes=250,CapturedUtc=now,UptimeSeconds=3600,Disks=[new("C:",1000,700,"")],Networks=[new("Ethernet","up",12500000,2500000,1000000000)]};
 var rows=AgentGaugeModel.Build(r,p);check("RAM gauge uses available memory",rows.Single(x=>x.Key=="ram").Percent==75);check("Windows drive retains letter and used percentage",rows.Single(x=>x.Key=="disk:C:").Percent==30);check("Network gauge uses larger full-duplex direction",rows.Single(x=>x.Key=="network:Ethernet").Percent==10);r.Networks=[r.Networks[0] with{LinkBitsPerSecond=0}];check("Unknown network capacity has no invented percent",AgentGaugeModel.Build(r,p).Single(x=>x.Key=="network:Ethernet").Percent==null);p.NetworkRules=[new("Ethernet",CapacityMbps:100)];check("Configured capacity overrides unknown link speed",AgentGaugeModel.Build(r,p).Single(x=>x.Key=="network:Ethernet").Percent==100);check("Windows network policy evaluates utilization",AgentChecks.Evaluate(r,p).Any(f=>f.Key=="network:Ethernet"));
 check("Fresh telemetry is current",!AgentGaugeModel.Stale(r,now,p,now));check("Missing connection makes gauges stale",AgentGaugeModel.Stale(r,null,p,now));check("Old capture is stale despite recent contact",AgentGaugeModel.Stale(withCapture(now.AddHours(-1)),now,p,now));
 AgentReport withCapture(DateTime time)=>new(){CapturedUtc=time};
 r.Os="Linux Debian";r.Disks=[];r.Linux=new(){Volumes=[new("/boot","/dev/sda2","ext4","раздел","8:2","/",2000,220,1780,0,1000,900)]};check("Linux gauge preserves boot mount and used bytes",AgentGaugeModel.Build(r,p).Single(x=>x.Key=="disk:/boot").Percent==11);check("Linux gauge details include filesystem and inode",AgentGaugeModel.Build(r,p).Single(x=>x.Key=="disk:/boot").Detail.Contains("ext4")&&AgentGaugeModel.Build(r,p).Single(x=>x.Key=="disk:/boot").Detail.Contains("Inode"));
 var nets=ServerNetworkRules.Validate(["192.168.20.0/24","192.168.20.0/24"]);check("Trusted network duplicates are removed",nets.Length==1);check("Trusted network accepts current client",ServerNetworkRules.Allows(nets,IPAddress.Parse("192.168.20.254")));check("Removed subnet does not authorize client",!ServerNetworkRules.Allows(nets,IPAddress.Parse("192.168.200.3")));check("Mapped IPv4 uses same allowlist",ServerNetworkRules.Allows(nets,IPAddress.Parse("::ffff:192.168.20.254")));try{ServerNetworkRules.Validate(["0.0.0.0/0"]);check("Public wildcard rejected",false);}catch(FormatException){check("Public wildcard rejected",true);}try{ServerNetworkRules.Validate(["192.168.20.0/24';whoami"]);check("Firewall command injection rejected",false);}catch(FormatException){check("Firewall command injection rejected",true);}
 check("Firewall command targets only application rule",ServerNetworkRules.FirewallCommand(nets).Contains("'SysAdminAssistantServer-LAN'")&&!ServerNetworkRules.FirewallCommand(nets).Contains("New-NetFirewallRule"));
 }
}
